// Keep customer messages only. Text and photos (prescriptions) are both accepted.
const m = $json.messages?.[0];
if (!m) return [];

return [{
  json: {
    customer_id: m.from,
    customer_name: $json.contacts?.[0]?.profile?.name || '',
    wa_phone_id: $json.metadata.phone_number_id,
    type: m.type,
    text: m.text?.body || m.image?.caption || '',
    media_id: m.image?.id || ''
  }
}];

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{
  json: {
    ...$('Normalize Message').first().json,
    b64: buf.toString('base64'),
    mime: $input.first().binary.data.mimeType || 'image/jpeg',
    prompt: 'This is a photo of an Egyptian prescription or medicine box. Return JSON only: {"is_prescription": true|false, "readable": true|false, "medicines": [{"name": "", "strength": "", "qty": 1}]}. qty = boxes requested, default 1. Never guess an unreadable name: put it as "?".'
  }
}];

const src = $('AI Read Request').first().json;
const raw = src.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let r = {};
try {
  r = JSON.parse(raw);
} catch (e) {
  r = { is_prescription: false, readable: false, medicines: [] };
}

const cat = $input.all().map(i => i.json);
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

function lev(a, b) {
  const m = a.length, n = b.length;
  if (!m) return n;
  if (!n) return m;
  const dp = Array.from({ length: m + 1 }, (_, i) => [i]);
  for (let j = 1; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] = a[i - 1] === b[j - 1]
        ? dp[i - 1][j - 1]
        : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
    }
  }
  return dp[m][n];
}

const lines = [];
const unclear = [];

for (const m of r.medicines || []) {
  const n = norm(m.name);
  if (!n || m.name === '?') {
    unclear.push(m.name || '?');
    continue;
  }

  const best = cat.map(p => ({
    p,
    d: Math.min(lev(n, norm(p.name)), lev(n, norm(p.active_ingredient)))
  })).sort((a, b) => a.d - b.d)[0];

  if (!best || best.d > Math.max(2, n.length * 0.3)) {
    unclear.push(m.name);
    continue;
  }

  const p = best.p;
  const qty = Math.max(1, Math.min(5, Math.round(Number(m.qty) || 1)));
  const alts = cat.filter(x =>
    x.sku !== p.sku &&
    x.active_ingredient === p.active_ingredient &&
    x.strength === p.strength &&
    Number(x.stock) >= qty
  );

  lines.push({
    sku: p.sku,
    name: p.name + ' ' + p.strength,
    qty,
    price: Number(p.price_egp),
    in_stock: Number(p.stock) >= qty,
    controlled: p.controlled === 'yes',
    fuzzy: best.d > 0,
    alternative: !(Number(p.stock) >= qty) && alts[0]
      ? alts[0].name + ' ' + alts[0].strength + ' (' + alts[0].sku + ', ' + alts[0].price_egp + ' EGP)'
      : ''
  });
}

const needsPharmacist = r.is_prescription || !r.readable || unclear.length > 0 || lines.some(l => l.controlled || !l.in_stock || l.fuzzy);
const group = 'R-' + $now.setZone('Africa/Cairo').toFormat('yyMMdd') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();

return [{
  json: {
    ...src,
    b64: undefined,
    prompt: undefined,
    group,
    lines,
    unclear,
    readable: r.readable !== false,
    needsPharmacist,
    nothing: !lines.length && !unclear.length,
    total: lines.filter(l => l.in_stock).reduce((s, l) => s + l.qty * l.price, 0)
  }
}];

const j = $input.first().json;
const customer = $('Normalize Message').first().json;

const status = j.needsPharmacist ? 'pending_pharmacist' : 'reserved';
const exp = $now.setZone('Africa/Cairo').plus({ hours: 2 }).toFormat('yyyy-MM-dd HH:mm');

const base = {
  customer_id: j.customer_id || customer.customer_id,
  wa_phone_id: j.wa_phone_id || customer.wa_phone_id,
  customer_name: j.customer_name || customer.customer_name
};

const rows = (j.lines || []).map(l => ({
  ...base,
  sku: l.sku,
  name: l.name,
  qty: l.qty,
  total_egp: l.qty * l.price,
  status,
  expires_at: status === 'reserved' ? exp : '',
  note: [
    l.controlled ? 'controlled' : '',
    l.in_stock ? '' : 'out of stock',
    l.alternative ? 'alt: ' + l.alternative : '',
    l.fuzzy ? 'fuzzy match' : ''
  ].filter(Boolean).join('; ')
}));

for (const u of (j.unclear || [])) {
  rows.push({
    ...base,
    sku: '',
    name: String(u),
    qty: 1,
    total_egp: 0,
    status: 'pending_pharmacist',
    expires_at: '',
    note: 'not in catalog or unreadable'
  });
}

return rows.map((r, k) => ({
  json: {
    res_id: j.group + '-' + (k + 1),
    ...r
  }
}));

const cat = Object.fromEntries($('Read Catalog').all().map(i => [i.json.sku, Number(i.json.stock)]));
for (const l of $('Match Catalog').first().json.lines) {
  cat[l.sku] -= l.qty;
  if (cat[l.sku] < 0) throw new Error('VALIDATION: stock for ' + l.sku + ' would go negative');
}
return $('Match Catalog').first().json.lines.map(l => ({ json: { sku: l.sku, stock: cat[l.sku] } }));

