const q = $json.callback_query;
const [, action, group, customer] = String(q.data || '').split(':');
if (!group) return [];
return [{
  json: {
    action,
    group,
    customer,
    query_id: q.id,
    chat_id: q.message.chat.id,
    message_id: q.message.message_id,
    original: q.message.text,
    by: q.from.username || q.from.first_name
  }
}];

const d = $('Parse Dicestion').first().json;
const lines = $('Get row(s) in sheet').all().map(i => i.json).filter(l => String(l.res_id).startsWith(d.group + '-'));
const stock = Object.fromEntries($input.all().map(i => [i.json.sku, Number(i.json.stock)]));

if (!lines.length) {
  return [{ json: { ...d, ok: false, toast: 'Already decided or not found' } }];
}

if (d.action === 'approve') {
  for (const l of lines) {
    stock[l.sku] -= Number(l.qty);
    if (stock[l.sku] < 0) {
      return [{ json: { ...d, ok: false, toast: 'Not enough stock for ' + l.name + '. Edit the request or reject.' } }];
    }
  }
}

const exp = $now.setZone('Africa/Cairo').plus({ hours: 2 }).toFormat('yyyy-MM-dd HH:mm');

return [{
  json: {
    ...d,
    ok: true,
    toast: d.action === 'approve' ? 'Approved' : 'Rejected',
    lines,
    newStock: [...new Set(lines.map(l => l.sku).filter(Boolean))].map(s => ({ sku: s, stock: stock[s] })),
    exp,
    wa_phone_id: lines[0].wa_phone_id,
    total: lines.reduce((s, l) => s + Number(l.total_egp), 0)
  }
}];

const d = $('Apply Decision').first().json;

return d.lines.map(l => ({
  json: {
    res_id: l.res_id,
    status: d.action === 'approve' ? 'reserved' : 'rejected',
    expires_at: d.action === 'approve' ? d.exp : '',
    pharmacist: d.by
  }
}));
